using FixFinder.Core.Engine;
using FixFinder.Core.Execution;
using FixFinder.Core.Http;
using FixFinder.Core.LocalFixes;
using FixFinder.Core.Sources;

namespace FixFinder.Tests;

/// <summary>
/// The mistakes of a computer science degree past the first weeks - data structures and algorithms, systems programming in C,
/// operating systems and concurrency, networks, databases, web and async code - each run through FixFinder for real, and fixed.
/// </summary>
/// <remarks>
/// Live. Each case skips when its toolchain is missing, and a skip looks like a pass. Freshly built C and C++ programs can be
/// refused by Application Control on a machine enforcing it, which fails the case for a reason that is not the rule's.
/// </remarks>
public class CourseworkTests
{
    /// <summary>The toolchain, the program, its files, the one run, what is typed in, the answer's id, and text the copied fix must contain.</summary>
