    [Theory]
    [MemberData(nameof(Programs))]
    public async Task TheMistakeIsFixed(
        string toolchain, string program, Dictionary<string, string> files, string chosen, string? input, string id, string expected)
    {
        if (!LocalFixLiveTests.Available(toolchain)) return;

        using var temp = new TempFolder();

        foreach (var (name, text) in files)
            File.WriteAllText(Path.Combine(temp.Path, name), text);

        var plan = TargetFactory.FromFile(Path.Combine(temp.Path, chosen), TimeSpan.FromMinutes(3));
        Assert.True(plan.Ok, plan.Problem);
        if (input is not null) plan = plan with { Spec = plan.Spec!.WithInput(input) };

        using var http = new FixFinderHttpClient();
        var outcome = await new FixFinderSession(http, new FixSourceRegistry()).RunAsync(plan, new SearchBudget(Cache: CacheMode.CacheOnly));

        Assert.True(outcome.Result == SessionResult.FoundFix, $"{program}: {outcome.Result} - {outcome.Headline}");
        Assert.Equal(id, outcome.Best!.Id);

        var copied = PasteableFix.For(new ExaminedCandidate(outcome.Best, 1, outcome.Candidates.Count, outcome.Harvest, outcome.Plan));

        Assert.NotNull(copied);
        Assert.Contains(expected, copied!.Text.ReplaceLineEndings("\n"), StringComparison.Ordinal);
    }
}
